public ImportByDing(Integer peopleId) {
        super(App.mainFrame, "通过钉钉通讯录导入");
        setContentPane(contentPane);
        setModal(true);
        ComponentUtil.setPreferSizeAndLocateToCenter(this, 0.3, 0.2);
        getRootPane().setDefaultButton(dingImportAllButton);

        this.peopleId = peopleId;
        tPeople = peopleMapper.selectByPrimaryKey(peopleId);

        dingDeptsImportButton.setIcon(new FlatSVGIcon("icon/import.svg"));
        dingImportAllButton.setIcon(new FlatSVGIcon("icon/import.svg"));
        dingDeptsRefreshButton.setIcon(new FlatSVGIcon("icon/refresh.svg"));

        // 钉钉-按部门导入-刷新
        dingDeptsRefreshButton.addActionListener(e -> ThreadUtil.execute(() -> {
            try {
                // 获取部门列表
                String accessToken = DingMsgSender.getAccessTokenTimedCache(tPeople.getAccountId()).get("accessToken");
                JSONObject response = DingTalkApiUtil.get("https://oapi.dingtalk.com/department/list?access_token=" + accessToken);
                if (response.getIntValue("errcode") != 0) {
                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "刷新失败！\n\n" + response.getString("errmsg"), "失败",
                            JOptionPane.ERROR_MESSAGE));
                    return;
                }
                JSONArray departmentList = response.getJSONArray("department");
                List<String> deptNames = new ArrayList<>();
                for (int i = 0; i < departmentList.size(); i++) {
                    JSONObject department = departmentList.getJSONObject(i);
                    deptNames.add(department.getString("name"));
                    wxCpDeptNameToIdMap.put(department.getString("name"), department.getLong("id"));
                    wxCpIdToDeptNameMap.put(department.getLong("id"), department.getString("name"));
                }
                UiThreadUtil.runOnUi(() -> {
                    dingDeptsComboBox.removeAllItems();
                    for (String deptName : deptNames) {
                        dingDeptsComboBox.addItem(deptName);
                    }
                });
            } catch (Exception ex) {
                UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "刷新失败！\n\n" + ex, "失败",
                        JOptionPane.ERROR_MESSAGE));
                logger.error(ExceptionUtils.getStackTrace(ex));
            }
        }));

        // 钉钉-按部门导入-导入
        dingDeptsImportButton.addActionListener(e -> {
            ThreadUtil.execute(() -> {
                PeopleEditForm peopleEditForm = PeopleEditForm.getInstance();
                JProgressBar progressBar = peopleEditForm.getMemberTabImportProgressBar();
                JLabel memberCountLabel = peopleEditForm.getMemberTabCountLabel();

                if (dingDeptsComboBox.getSelectedItem() == null) {
                    return;
                }
                try {
                    UiThreadUtil.runOnUi(() -> {
                        progressBar.setVisible(true);
                        progressBar.setIndeterminate(true);
                    });
                    int importedCount = 0;
                    String now = SqliteUtil.nowDateForSqlite();

                    String dataVersion = UUID.fastUUID().toString(true);

                    // 获取部门id
                    Long deptId = wxCpDeptNameToIdMap.get(dingDeptsComboBox.getSelectedItem());

                    // 保存导入配置
                    TPeopleImportConfig beforePeopleImportConfig = peopleImportConfigMapper.selectByPeopleId(peopleId);

                    TPeopleImportConfig tPeopleImportConfig = new TPeopleImportConfig();
                    tPeopleImportConfig.setPeopleId(peopleId);
                    tPeopleImportConfig.setLastWay(String.valueOf(PeopleImportWayEnum.BY_DING_CODE));
                    tPeopleImportConfig.setLastDataVersion(dataVersion);
                    tPeopleImportConfig.setAppVersion(UiConsts.APP_VERSION);
                    tPeopleImportConfig.setModifiedTime(now);

                    DingImportConfig dingImportConfig = new DingImportConfig();
                    dingImportConfig.setUserType(2);
                    dingImportConfig.setDeptId(deptId);
                    tPeopleImportConfig.setLastWayConfig(JSONUtil.toJsonStr(dingImportConfig));

                    if (beforePeopleImportConfig != null) {
                        tPeopleImportConfig.setId(beforePeopleImportConfig.getId());
                        peopleImportConfigMapper.updateByPrimaryKeySelective(tPeopleImportConfig);
                    } else {
                        tPeopleImportConfig.setCreateTime(now);
                        peopleImportConfigMapper.insert(tPeopleImportConfig);
                    }

                    // 获取用户
                    String accessToken = DingMsgSender.getAccessTokenTimedCache(tPeople.getAccountId()).get("accessToken");

                    long offset = 0;
                    try (PeopleDataBatchInserter batcher = new PeopleDataBatchInserter(peopleDataMapper)) {
                        while (true) {
                            JSONObject response = DingTalkApiUtil.get("https://oapi.dingtalk.com/user/simplelist?access_token=" + accessToken
                                    + "&department_id=" + deptId + "&offset=" + offset + "&size=100");
                            if (response.getIntValue("errcode") != 0) {
                                final String errMsg = response.getString("errmsg");
                                if (response.getIntValue("errcode") == 60011) {
                                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "导入失败！\n\n" + errMsg + "\n\n进入开发者后台，在小程序或者微应用详情的「接口权限」模块，点击申请对应的通讯录接口读写权限", "失败",
                                            JOptionPane.ERROR_MESSAGE));
                                } else {
                                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "导入失败！\n\n" + errMsg, "失败", JOptionPane.ERROR_MESSAGE));
                                }

                                logger.error(response.getString("errmsg"));
                                return;
                            }
                            JSONArray userlist = response.getJSONArray("userlist");
                            if (userlist == null || userlist.isEmpty()) {
                                break;
                            }
                            for (int i = 0; i < userlist.size(); i++) {
                                JSONObject dingUser = userlist.getJSONObject(i);
                                String[] dataArray = new String[]{dingUser.getString("userid"), dingUser.getString("name")};

                                TPeopleData tPeopleData = new TPeopleData();
                                tPeopleData.setPeopleId(peopleId);
                                tPeopleData.setPin(dataArray[0]);
                                tPeopleData.setVarData(JSONUtil.toJsonStr(dataArray));
                                tPeopleData.setAppVersion(UiConsts.APP_VERSION);
                                tPeopleData.setDataVersion(dataVersion);
                                tPeopleData.setCreateTime(now);
                                tPeopleData.setModifiedTime(now);

                                batcher.add(tPeopleData);

                                importedCount++;
                                if (UiThreadUtil.shouldUpdateImportProgress(importedCount)) {
                                    int count = importedCount;
                                    UiThreadUtil.runOnUi(() -> memberCountLabel.setText(String.valueOf(count)));
                                }
                            }
                            offset += 100;
                        }
                    }

                    int finalCount = importedCount;
                    UiThreadUtil.runOnUi(() -> {
                        memberCountLabel.setText(String.valueOf(finalCount));
                        PeopleEditForm.initDataTable(peopleId);
                        JOptionPane.showMessageDialog(App.mainFrame, "导入完成！", "完成", JOptionPane.INFORMATION_MESSAGE);
                    });
                } catch (Exception ex) {
                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "导入失败！\n\n" + ex, "失败",
                            JOptionPane.ERROR_MESSAGE));
                    logger.error(ex.toString());
                } finally {
                    UiThreadUtil.runOnUi(() -> {
                        progressBar.setIndeterminate(false);
                        progressBar.setVisible(false);
                    });
                }

            });
        });

        // 钉钉-导入全部
        dingImportAllButton.addActionListener(e -> onOK());

        // call onCancel() when cross is clicked
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new WindowAdapter() {
            public void windowClosing(WindowEvent e) {
                onCancel();
            }
        });

        // call onCancel() on ESCAPE
        contentPane.registerKeyboardAction(e -> onCancel(), KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT);
    }

