package com.fangxuele.tool.push.ui.dialog.importway;

import cn.hutool.json.JSONUtil;
import com.fangxuele.tool.push.dao.TPeopleDataMapper;
import com.fangxuele.tool.push.dao.TPeopleImportConfigMapper;
import com.fangxuele.tool.push.dao.TPeopleMapper;
import com.fangxuele.tool.push.domain.TPeopleImportConfig;
import com.fangxuele.tool.push.ui.UiConsts;
import org.junit.*;

import java.awt.GraphicsEnvironment;

public class ReImportTests {

    static {
        // Set headless mode before any AWT/Swing classes are loaded
        System.setProperty("java.awt.headless", "true");
    }

    private TPeopleImportConfigMapper peopleImportConfigMapper;

    private TPeopleDataMapper peopleDataMapper;

    private TPeopleMapper peopleMapper;

    private Integer peopleId = 1;

    // Inner class to represent DingImportConfig for testing
    public static class DingImportConfig {
        private Integer userType;
        private Long deptId;

        public Integer getUserType() {
            return userType;
        }

        public void setUserType(Integer userType) {
            this.userType = userType;
        }

        public Long getDeptId() {
            return deptId;
        }

        public void setDeptId(Long deptId) {
            this.deptId = deptId;
        }
    }

    @Before
    public void setUp() throws Exception {
        // Initialize test objects
    }

    @After
    public void tearDown() throws Exception {
        // Cleanup
    }

    @Test
    public void testHeadlessMode() {
        Assert.assertTrue("Should be in headless mode", GraphicsEnvironment.isHeadless());
    }

    @Test
    public void testReImport_WhenPeopleImportConfigIsNull_ReturnsEarly() {
        TPeopleImportConfig config = null;
        Assert.assertNull(config);
    }

    @Test
    public void testReImport_WhenLastWayConfigIsNull_ReturnsEarly() {
        TPeopleImportConfig config = new TPeopleImportConfig();
        config.setLastWayConfig(null);
        Assert.assertNull(config.getLastWayConfig());
    }

    @Test
    public void testReImport_WhenDingImportConfigBeforeIsNull_ReturnsEarly() {
        TPeopleImportConfig config = new TPeopleImportConfig();
        config.setLastWayConfig("invalid-json");
        Assert.assertEquals("invalid-json", config.getLastWayConfig());
    }

    @Test
    public void testReImport_UserType1_DeletesExistingDataBeforeImport() {
        DingImportConfig dingConfig = new DingImportConfig();
        dingConfig.setUserType(1);

        TPeopleImportConfig config = new TPeopleImportConfig();
        config.setLastWayConfig(JSONUtil.toJsonStr(dingConfig));
        config.setId(100);

        Assert.assertEquals(Integer.valueOf(1), dingConfig.getUserType());
        Assert.assertEquals(Integer.valueOf(100), config.getId());
    }

    @Test
    public void testReImport_UserType2_DeletesExistingDataBeforeImport() {
        DingImportConfig dingConfig = new DingImportConfig();
        dingConfig.setUserType(2);
        dingConfig.setDeptId(123L);

        TPeopleImportConfig config = new TPeopleImportConfig();
        config.setLastWayConfig(JSONUtil.toJsonStr(dingConfig));
        config.setId(100);

        Assert.assertEquals(Integer.valueOf(2), dingConfig.getUserType());
        Assert.assertEquals(Long.valueOf(123L), dingConfig.getDeptId());
