public ImportByWxMp(Integer peopleId) {
        super(App.mainFrame, "通过微信公众平台导入人群");
        setContentPane(contentPane);
        setModal(true);
        ComponentUtil.setPreferSizeAndLocateToCenter(this, 0.3, 0.3);
        getRootPane().setDefaultButton(memberImportAllButton);

        this.peopleId = peopleId;
        tPeople = peopleMapper.selectByPrimaryKey(peopleId);

        memberImportAllButton.setIcon(new FlatSVGIcon("icon/import.svg"));
        memberImportTagButton.setIcon(new FlatSVGIcon("icon/import.svg"));
        memberImportTagRetainButton.setIcon(new FlatSVGIcon("icon/import.svg"));
        memberImportTagFreshButton.setIcon(new FlatSVGIcon("icon/refresh.svg"));

        // 公众号-导入全员按钮事件
        memberImportAllButton.addActionListener(e -> {
            boolean importBasicInfo = importOptionBasicInfoCheckBox.isSelected();
            boolean importAvatar = importOptionAvatarCheckBox.isSelected();
            ThreadUtil.execute(() -> importWxAll(importBasicInfo, importAvatar));
            dispose();
        });

        // 公众号-刷新可选的标签按钮事件
        memberImportTagFreshButton.addActionListener(e -> {
            WxMpService wxMpService = WxMpTemplateMsgSender.getWxMpService(tPeople.getAccountId());
            if (wxMpService.getWxMpConfigStorage() == null) {
                return;
            }
            memberImportTagFreshButton.setEnabled(false);
            UiThreadUtil.runOffUi(() -> {
                try {
                    List<WxUserTag> wxUserTagList = wxMpService.getUserTagService().tagGet();
                    Map<String, Long> newUserTagMap = new HashMap<>();
                    List<String> items = new ArrayList<>();
                    for (WxUserTag wxUserTag : wxUserTagList) {
                        String item = wxUserTag.getName() + "/" + wxUserTag.getCount() + "用户";
                        items.add(item);
                        newUserTagMap.put(item, wxUserTag.getId());
                    }
                    UiThreadUtil.runOnUi(() -> {
                        memberImportTagComboBox.removeAllItems();
                        userTagMap = newUserTagMap;
                        for (String item : items) {
                            memberImportTagComboBox.addItem(item);
                        }
                    });
                } catch (WxErrorException e1) {
                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "刷新失败！\n\n" + e1.getMessage(), "失败",
                            JOptionPane.ERROR_MESSAGE));
                    logger.error(e1);
                    e1.printStackTrace();
                } finally {
                    UiThreadUtil.runOnUi(() -> memberImportTagFreshButton.setEnabled(true));
                }
            });
        });

        // 公众号-导入选择的标签分组用户按钮事件(取并集)
        memberImportTagButton.addActionListener(e -> {
            Object selectedTagItem = memberImportTagComboBox.getSelectedItem();
            boolean importBasicInfo = importOptionBasicInfoCheckBox.isSelected();
            boolean importAvatar = importOptionAvatarCheckBox.isSelected();
            ThreadUtil.execute(() -> {
                PeopleEditForm peopleEditForm = PeopleEditForm.getInstance();
                JProgressBar progressBar = peopleEditForm.getMemberTabImportProgressBar();

                try {
                    if (selectedTagItem != null && StringUtils.isNotEmpty(selectedTagItem.toString())) {
                        Long selectedTagId = userTagMap.get(selectedTagItem);
                        if (selectedTagId == null) {
                            UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "请先选择需要导入的标签！", "提示",
                                    JOptionPane.INFORMATION_MESSAGE));
                            return;
                        }
                        getMpUserListByTag(selectedTagId, false, importBasicInfo, importAvatar);
                        UiThreadUtil.runOnUi(() -> {
                            PeopleEditForm.initDataTable(peopleId);
                            JOptionPane.showMessageDialog(App.mainFrame, "导入完成！", "完成",
                                    JOptionPane.INFORMATION_MESSAGE);
                        });
                    } else {
                        UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "请先选择需要导入的标签！", "提示",
                                JOptionPane.INFORMATION_MESSAGE));
                    }
                } catch (WxErrorException e1) {
                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "导入失败！\n\n" + e1.getMessage(), "失败",
                            JOptionPane.ERROR_MESSAGE));
                    logger.error(e1);
                } finally {
                    UiThreadUtil.runOnUi(() -> {
                        progressBar.setIndeterminate(false);
                        progressBar.setValue(progressBar.getMaximum());
                        progressBar.setVisible(false);
                    });
                }
            });
        });

        // 公众号-导入选择的标签分组用户按钮事件(取交集)
        memberImportTagRetainButton.addActionListener(e -> {
            Object selectedTagItem = memberImportTagComboBox.getSelectedItem();
            boolean importBasicInfo = importOptionBasicInfoCheckBox.isSelected();
            boolean importAvatar = importOptionAvatarCheckBox.isSelected();
            ThreadUtil.execute(() -> {
                PeopleEditForm peopleEditForm = PeopleEditForm.getInstance();
                JProgressBar progressBar = peopleEditForm.getMemberTabImportProgressBar();

                try {
                    if (selectedTagItem != null && StringUtils.isNotEmpty(selectedTagItem.toString())) {
                        Long selectedTagId = userTagMap.get(selectedTagItem);
                        if (selectedTagId == null) {
                            UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "请先选择需要导入的标签！", "提示",
                                    JOptionPane.INFORMATION_MESSAGE));
                            return;
                        }
                        getMpUserListByTag(selectedTagId, true, importBasicInfo, importAvatar);
                        UiThreadUtil.runOnUi(() -> {
                            PeopleEditForm.initDataTable(peopleId);
                            JOptionPane.showMessageDialog(App.mainFrame, "导入完成！", "完成",
                                    JOptionPane.INFORMATION_MESSAGE);
                        });
                    } else {
                        UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "请先选择需要导入的标签！", "提示",
                                JOptionPane.INFORMATION_MESSAGE));
                    }
                } catch (WxErrorException e1) {
                    UiThreadUtil.runOnUi(() -> JOptionPane.showMessageDialog(App.mainFrame, "导入失败！\n\n" + e1.getMessage(), "失败",
                            JOptionPane.ERROR_MESSAGE));
                    logger.error(e1);
                    e1.printStackTrace();
                } finally {
                    UiThreadUtil.runOnUi(() -> {
                        progressBar.setIndeterminate(false);
                        progressBar.setValue(progressBar.getMaximum());
                        progressBar.setVisible(false);
                    });
                }
            });
        });

        // 公众号-清空本地缓存按钮事件
        clearDbCacheButton.addActionListener(e -> {
            int count = tWxMpUserMapper.deleteAll();
            JOptionPane.showMessageDialog(App.mainFrame, "清理完毕！\n\n共清理：" + count + "条本地数据", "提示",
                    JOptionPane.INFORMATION_MESSAGE);
        });

        // call onCancel() when cross is clicked
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        addWindowListener(new WindowAdapter() {
            public void windowClosing(WindowEvent e) {
                onCancel();
            }
        });

        // call onCancel() on ESCAPE
        contentPane.registerKeyboardAction(e -> onCancel(), KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT);
    }

