package com.fangxuele.tool.push.ui.dialog.importway;

import com.fangxuele.tool.push.domain.TPeopleImportConfig;
import org.junit.*;

import java.awt.GraphicsEnvironment;
import java.lang.reflect.Field;

import static org.junit.Assert.*;
import static org.junit.Assume.assumeFalse;

public class ReImport1Tests {

    private Integer testPeopleId = 1;
    private ImportByWxMp importByWxMp;

    @Before
    public void setUp() throws Exception {
        // Only create GUI components if not in headless mode
        if (!GraphicsEnvironment.isHeadless()) {
            importByWxMp = new ImportByWxMp(testPeopleId);
        }
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }

    @Test
    public void testImportByWxMpCreation() throws Exception {
        // Skip this test in headless environment
        assumeFalse("Test requires non-headless environment", GraphicsEnvironment.isHeadless());

        assertNotNull(importByWxMp);

        // Verify peopleId is set correctly
        Field peopleIdField = findField(importByWxMp.getClass(), "peopleId");
        peopleIdField.setAccessible(true);
        Integer peopleId = (Integer) peopleIdField.get(importByWxMp);
        assertEquals(testPeopleId, peopleId);
    }

    @Test
    public void testEmptyLastWayConfig() {
        // This test doesn't need GUI - it tests a simple POJO
        TPeopleImportConfig peopleImportConfig = new TPeopleImportConfig();
        peopleImportConfig.setLastWayConfig(null);
        assertNull(peopleImportConfig.getLastWayConfig());

        peopleImportConfig.setLastWayConfig("");
        assertEquals("", peopleImportConfig.getLastWayConfig());
    }

    @After
    public void tearDown() {
        // Reset tagUserSet after each test
        if (importByWxMp != null) {
            try {
                setPrivateField(importByWxMp, "tagUserSet", null);
            } catch (Exception e) {
                // Ignore cleanup errors
            }
        }
    }
}

