package com.fangxuele.tool.push.ui.dialog.importway;

import cn.hutool.json.JSONUtil;
import com.fangxuele.tool.push.domain.TPeople;
import me.chanjar.weixin.cp.bean.WxCpUser;
import me.chanjar.weixin.cp.bean.Gender;
import org.junit.*;

import java.util.HashMap;
import java.util.Map;

public class ReImport2Tests {

    private static final Integer PEOPLE_ID = 1;
    private static final Integer ACCOUNT_ID = 100;

    private Map<Integer, String> wxCpIdToDeptNameMap;

    @Before
    public void setUp() throws Exception {
        wxCpIdToDeptNameMap = new HashMap<>();
        wxCpIdToDeptNameMap.put(1, "Department1");
        wxCpIdToDeptNameMap.put(2, "Department2");
    }

    @After
    public void tearDown() {
        // Cleanup if needed
    }

    @Test
    public void testJsonSerialization() {
        Map<String, Object> config = new HashMap<>();
        config.put("userType", 1);
        config.put("tagId", "tag123");
        config.put("depId", 1L);

        String json = JSONUtil.toJsonStr(config);
        Assert.assertNotNull("JSON should not be null", json);
        Assert.assertTrue("JSON should contain userType", json.contains("userType"));
    }

    @Test
    public void testWxCpUserCreation() {
        WxCpUser user = createWxCpUser("user1", "User One", 1, new Long[]{1L});
        Assert.assertEquals("user1", user.getUserId());
        Assert.assertEquals("User One", user.getName());
    }

    @Test
    public void testWxCpUserWithNullDepartIds() {
        WxCpUser user = createWxCpUser("user1", "User One", 1, null);
        Assert.assertEquals("user1", user.getUserId());
        Assert.assertNull(user.getDepartIds());
    }

    @Test
    public void testWxCpUserWithMultipleDepartIds() {
        WxCpUser user = createWxCpUser("user1", "User One", 1, new Long[]{1L, 2L});
        Assert.assertEquals(2, user.getDepartIds().length);
    }

    @Test
    public void testTPeopleCreation() {
        TPeople tPeople = new TPeople();
        tPeople.setId(PEOPLE_ID);
        tPeople.setAccountId(ACCOUNT_ID);
        Assert.assertEquals(PEOPLE_ID, tPeople.getId());
        Assert.assertEquals(ACCOUNT_ID, tPeople.getAccountId());
    }

    @Test
    public void testWxCpIdToDeptNameMap() {
        Assert.assertEquals("Department1", wxCpIdToDeptNameMap.get(1));
        Assert.assertEquals("Department2", wxCpIdToDeptNameMap.get(2));
    }

    private WxCpUser createWxCpUser(String userId, String name, Integer status, Long[] departIds) {
        WxCpUser user = new WxCpUser();
        user.setUserId(userId);
        user.setName(name);
        user.setStatus(status);
        user.setDepartIds(departIds);
        user.setGender(Gender.MALE);
        user.setEmail("test@example.com");
        user.setPosition("Developer");
        return user;
    }
}

