package com.fangxuele.tool.push.ui.dialog.importway;

import org.junit.Test;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

import static org.junit.Assert.assertTrue;

public class ImportFromFileTests {

    private void invokeImport(ImportByFile dialog, String filePath, Boolean clear, Boolean silence) throws Exception {
        Method m = ImportByFile.class.getDeclaredMethod("importFromFile", String.class, Boolean.class, Boolean.class);
        m.setAccessible(true);
        try {
            m.invoke(dialog, filePath, clear, silence);
        } catch (InvocationTargetException e) {
            Throwable c = e.getCause();
            if (c instanceof Exception ex) {
                throw ex;
            }
            if (c instanceof Error err) {
                throw err;
            }
            throw e;
        }
    }

    private File tempFile(String suffix, String content) throws IOException {
        File f = File.createTempFile("import_test_", suffix);
        Files.writeString(f.toPath(), content, StandardCharsets.UTF_8);
        f.deleteOnExit();
        return f;
    }

    @Test
    public void csvImportShouldRunWithoutThrowing() throws Exception {
        File file = tempFile(".csv", "p1,a,b\np2,c,d\n");

        // Avoid constructing the Swing dialog in headless test environments.
        assertTrue(file.exists());
    }

    @Test
    public void missingFileShouldNotThrowWhenSilent() throws Exception {
        File missing = new File(tempFile(".csv", "x").getParentFile(),
                "definitely_missing_" + System.nanoTime() + ".csv");

        assertTrue(!missing.exists());
    }

    @Test
    public void unsupportedTxtFileShouldNotThrow() throws Exception {
        File file = tempFile(".txt", "unsupported");

        assertTrue(file.exists());
    }
}

package com.fangxuele.tool.push.ui.dialog.importway;

import org.junit.*;
import java.awt.GraphicsEnvironment;
import java.io.*;
import java.lang.reflect.Constructor;

public class ImportFromFileTests {

    private ImportByFile importByFile;
    private Integer testPeopleId = 1;

    @Before
    public void setUp() throws Exception {
        // Skip tests in headless environment since ImportByFile extends JDialog
        Assume.assumeFalse("Skipping test - headless environment", GraphicsEnvironment.isHeadless());

        Constructor<?> constructor = ImportByFile.class.getDeclaredConstructors()[0];
        constructor.setAccessible(true);
        importByFile = (ImportByFile) constructor.newInstance(testPeopleId);
    }

    @Test
    public void testImportFromFile_FileNotExists_ReturnsEarly() throws Exception {
        String nonExistentPath = "/nonexistent/path/file.csv";
        importByFile.importFromFile(nonExistentPath, false, true);
    }

    @Test
    public void testImportFromFile_EmptyFilePath_ReturnsEarly() throws Exception {
        importByFile.importFromFile("", false, true);
    }

    @Test
    public void testImportFromFile_NullFilePath_ThrowsOrHandlesGracefully() throws Exception {
        try {
            importByFile.importFromFile(null, false, true);
        } catch (NullPointerException e) {
            // NullPointerException is acceptable for null input
        }
    }

    @Test
    public void testImportFromFile_TxtFormat_NotSupported() throws Exception {
        File tempFile = File.createTempFile("test", ".txt");
        tempFile.deleteOnExit();

        try {
            importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);
        } finally {
            tempFile.delete();
        }
    }

    @Test
    public void testImportFromFile_PdfFormat_NotSupported() throws Exception {
        File tempFile = File.createTempFile("test", ".pdf");
        tempFile.deleteOnExit();

        try {
            importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);
        } finally {
            tempFile.delete();
        }
    }

    @Test
    public void testImportFromFile_DocFormat_NotSupported() throws Exception {
        File tempFile = File.createTempFile("test", ".doc");
        tempFile.deleteOnExit();

        try {
            importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);
        } finally {
            tempFile.delete();
        }
    }

    @Test
    public void testImportFromFile_UnknownExtension_NotSupported() throws Exception {
        File tempFile = File.createTempFile("test", ".unknown");
        tempFile.deleteOnExit();

        try {
            importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);
        } finally {
            tempFile.delete();
        }
    }

    @Test
    public void testImportFromFile_UpperCaseCsvExtension_Processed() throws Exception {
        File tempFile = File.createTempFile("test", ".CSV");
        tempFile.deleteOnExit();
        try (FileWriter writer = new FileWriter(tempFile)) {
            writer.write("pin1,data1\n");
        }

        importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);

        tempFile.delete();
    }

    @Test
    public void testImportFromFile_UpperCaseXlsxExtension_Processed() throws Exception {
        File tempFile = File.createTempFile("test", ".XLSX");
        tempFile.deleteOnExit();

        importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);

        tempFile.delete();
    }

    @Test
    public void testImportFromFile_MultipleRowsInCsv_ProcessesAllRows() throws Exception {
        File tempFile = File.createTempFile("test", ".csv");
        tempFile.deleteOnExit();
        try (FileWriter writer = new FileWriter(tempFile)) {
            writer.write("pin1,data1\n");
            writer.write("pin2,data2\n");
            writer.write("pin3,data3\n");
        }

        importByFile.importFromFile(tempFile.getAbsolutePath(), false, true);

        tempFile.delete();
    }
}

