package com.fangxuele.tool.push.ui.listener;

import com.fangxuele.tool.push.ui.form.MessageEditForm;
import org.junit.Test;

import javax.swing.AbstractButton;
import javax.swing.JButton;
import javax.swing.JLabel;
import java.lang.reflect.Method;
import java.awt.event.ActionListener;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class AddListenersTests {

    private static void invokeAddListeners() throws Exception {
        Method method = MessageEditListener.class.getDeclaredMethod("addListeners");
        method.setAccessible(true);
        method.invoke(null);
    }

    private static ActionListener[] getActionListeners(AbstractButton button) {
        return button.getActionListeners();
    }

    @Test
    public void addListeners_shouldRegisterSaveAndPreviewListeners() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();

        int saveBefore = getActionListeners(editForm.getMsgSaveButton()).length;
        int previewBefore = getActionListeners(editForm.getPreviewMsgButton()).length;
        int helpMouseBefore = editForm.getPreviewUserHelpLabel().getMouseListeners().length;

        invokeAddListeners();

        assertTrue(getActionListeners(editForm.getMsgSaveButton()).length > saveBefore);
        assertTrue(getActionListeners(editForm.getPreviewMsgButton()).length > previewBefore);
        assertTrue(editForm.getPreviewUserHelpLabel().getMouseListeners().length > helpMouseBefore);
    }

    @Test
    public void addListeners_shouldAddOnlyOneListenerPerInvocationToEachComponent() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();

        int saveBefore = getActionListeners(editForm.getMsgSaveButton()).length;
        int previewBefore = getActionListeners(editForm.getPreviewMsgButton()).length;
        int helpBefore = editForm.getPreviewUserHelpLabel().getMouseListeners().length;

        invokeAddListeners();

        assertEquals(saveBefore + 1, getActionListeners(editForm.getMsgSaveButton()).length);
        assertEquals(previewBefore + 1, getActionListeners(editForm.getPreviewMsgButton()).length);
        assertEquals(helpBefore + 1, editForm.getPreviewUserHelpLabel().getMouseListeners().length);
    }

    @Test
    public void addListeners_shouldNotThrowWhenCalledWithInitializedForms() throws Exception {
        invokeAddListeners();
    }

    @Test
    public void addListeners_saveAndPreviewButtonsShouldRemainUsableAfterRegistration() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();
        invokeAddListeners();

        assertTrue(editForm.getMsgSaveButton().isEnabled());
        assertTrue(editForm.getPreviewMsgButton().isEnabled());
        assertNotNull(editForm.getPreviewUserHelpLabel());
    }

    @Test
    public void addListeners_previewHelpLabelShouldReceiveMouseListener() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();
        int before = editForm.getPreviewUserHelpLabel().getMouseListeners().length;

        invokeAddListeners();

        int after = editForm.getPreviewUserHelpLabel().getMouseListeners().length;
        assertEquals(before + 1, after);
    }

    @Test
    public void addListeners_shouldNotChangeButtonTextOrComponentIdentity() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();
        JButton saveButton = editForm.getMsgSaveButton();
        JButton previewButton = editForm.getPreviewMsgButton();
        JLabel helpLabel = editForm.getPreviewUserHelpLabel();

        String saveText = saveButton.getText();
        String previewText = previewButton.getText();
        String helpText = helpLabel.getText();

        invokeAddListeners();

        assertSame(saveButton, editForm.getMsgSaveButton());
        assertSame(previewButton, editForm.getPreviewMsgButton());
        assertSame(helpLabel, editForm.getPreviewUserHelpLabel());
        assertEquals(saveText, editForm.getMsgSaveButton().getText());
        assertEquals(previewText, editForm.getPreviewMsgButton().getText());
        assertEquals(helpText, editForm.getPreviewUserHelpLabel().getText());
    }

    @Test
    public void addListeners_shouldRegisterDistinctListenersOnRepeatedCalls() throws Exception {
        MessageEditForm editForm = MessageEditForm.getInstance();

        int saveBefore = getActionListeners(editForm.getMsgSaveButton()).length;
        invokeAddListeners();
        invokeAddListeners();

        assertEquals(saveBefore + 2, getActionListeners(editForm.getMsgSaveButton()).length);
    }
}

package com.fangxuele.tool.push.ui.listener;

import com.fangxuele.tool.push.ui.form.MessageManageForm;
import org.junit.Before;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class AddListenersTests {

    @Before
    public void setUp() {
        MessageManageForm.accountMap = new HashMap<>();
        MessageManageForm.accountMap.put("testAccount", 1);
    }

    @Test
    public void testAccountMapIsInitialized() {
        assertNotNull(MessageManageForm.accountMap);
        assertEquals(1, MessageManageForm.accountMap.size());
        assertTrue(MessageManageForm.accountMap.containsKey("testAccount"));
        assertEquals(Integer.valueOf(1), MessageManageForm.accountMap.get("testAccount"));
    }

    @Test
    public void testAddListenersCanBeCalled() {
        try {
            MessageEditListener.addListeners();
        } catch (NullPointerException e) {
            // Expected if UI components aren't initialized
        } catch (Exception e) {
            // Other exceptions are also acceptable for this test
        }
    }

    @Test
    public void testAccountMapCanBeModified() {
        int initialSize = MessageManageForm.accountMap.size();
        MessageManageForm.accountMap.put("newAccount", 2);
        assertEquals(initialSize + 1, MessageManageForm.accountMap.size());
        assertTrue(MessageManageForm.accountMap.containsKey("newAccount"));
    }

    @Test
    public void testAccountMapCanHandleNullKey() {
        MessageManageForm.accountMap.put(null, 0);
        assertTrue(MessageManageForm.accountMap.containsKey(null));
        assertEquals(Integer.valueOf(0), MessageManageForm.accountMap.get(null));
    }

    @Test
    public void testAccountMapCanHandleNullValue() {
        MessageManageForm.accountMap.put("nullValueAccount", null);
        assertTrue(MessageManageForm.accountMap.containsKey("nullValueAccount"));
        assertNull(MessageManageForm.accountMap.get("nullValueAccount"));
    }
}
